INSERT INTO `courses` VALUES (1,'b5r942mjfak761itbo970xoq','พื้นฐานภาษาอังกฤษ','tgat',2000,1,'standard','0000-00-00 00:00:00','2025-03-02 06:39:27',NULL,1,1,NULL,20,'TGAT คืออะไร ? TGAT หรือ Thailand General Aptitude Test คือวิชาที่วัดความถนัดทั่วไป มีด้วยกันทั้งหมด 3 พาร์ท คือ English Communication (การสื่อสารภาษาอังกฤษ) Critical and Logical Thinking (การคิดอย่างมีเหตุผล) GAT คืออะไร ? TGAT หรือ Thailand General Aptitude Test คือวิชาที่วัดความถนัดทั่วไป มีด้วยกันทั้งหมด 3 พาร์ท คือ English Communication (การสื่อสารภาษาอังกฤษ) Critical and Logical Thinking (การคิดอย่างมีเหตุผล)GAT คืออะไร ? TGAT หรือ Thailand General Aptitude Test คือวิชาที่วัดความถนัดทั่วไป มีด้วยกันทั้งหมด 3 พาร์ท คือ English Communication (การสื่อสารภาษาอังกฤษ) Critical and Logical Thinking (การคิดอย่างมีเหตุผล)','Basic English','A-LEVEL ENGLISH','8'),(3,'mwh71za9i86rn020hprvklzs','พื้นฐานฟิสิกส์','a-level',2000,1,'premium','0000-00-00 00:00:00','2025-03-02 06:39:35',NULL,1,1,NULL,24,'ข้อสอบวิชาฟิสิกส์ A-Level คือข้อสอบที่มาแทนวิชาฟิสิกส์สามัญ เนื้อหาที่ออกข้อสอบจะมาจากเนื้อหาที่ได้เรียน โดยเน้นการนำไปประยุกต์ใช้ แบ่งเป็น 5 พาร์ทด้วยกัน ได้แก่ กลศาสตร์, คลื่นกลและแสง, ไฟฟ้าแม่เหล็กและคลื่นแม่เหล็กไฟฟ้า, อุณหพลศาสตร์และสมบัติเชิงกลของสารและฟิสิกส์แผนใหม่ ข้อสอบแบ่งเป็นปรนัย 5 ตัวเลือก 25 ข้อและอัตนัยในรูปแบบเลือกระบายค่าตัวเลขจำนวน 5 ข้อ รวมคะแนนทั้งสิ้นเต็ม 100 คะแนน ซึ่งข้อสอบจะมีความแตกต่างจากวิชาคณิตศาสตร์ประยุกต์1 และ 2 ที่ตัวข้อสอบอัตนัยจะไม่ได้เป็นข้อเขียนเต็มนั่นเอง\n\nระยะเวลาสอบ: 90 นาที\nจำนวนคะแนน: 30 ข้อคะแนนเต็ม 100 คะแนน (ปรนัย 26 ข้อ = 75 คะแนน / อัตนัย 4 ข้อ = 25 คะแนน)\nค่าสอบ: 100.-\nใครควรสอบ: น้องๆ สายวิทย์-คณิต \nข้อสอบออกอะไรบ้าง ? :\nกลศาสตร์ ธรรมชาติและพัฒนาการทางฟิสิกส์, การเคลื่อนที่แนวตรง, แรงและกฎการเคลื่อนที่, สมดุลกลของวัตถุ, งานและกฎการอนุรักษ์พลังงานกล, โมเมนตัมและการชน, การเคลื่อนที่แนวโค้งและการเคลื่อนที่แบบฮาร์มอนิกส์อย่างง่าย\nคลื่นกลและแสง แสง คลื่นและเสียง\nไฟฟ้าแม่เหล็กและคลื่นแม่เหล็กไฟฟ้า ไฟฟ้าสถิต, ไฟฟ้ากระแส, แม่เหล็กและไฟฟ้าและคลื่นแม่เหล็กไฟฟ้า\nอุณหพลศาสตร์และสมบัติเชิงกลของสาร ความร้อนและแก๊ส ของแข็งและของไหล\nฟิสิกส์แผนใหม่ ฟิสิกส์อะตอมและฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค','Basic Physics','A-LEVEL PHYSICS','10'),(12,'q4wvtdq484brc82jpr3019d5','พิชิต Tpat 1 60 +','tpat',899,1,'premium','0000-00-00 00:00:00','2025-03-02 06:39:39',NULL,1,1,NULL,24,'TPAT1 พาร์ตเชาวน์ปัญญา\n\nมี 45 ข้อ เวลาสอบ 75 นาที เฉล่ียเวลาข้อละ 1 นาที 40 วินาที\nข้อสอบเป็นปรนัย 5 ตัวเลือก ทุกข้อคะแนนเท่ากัน คะแนนรวม 100 คะแนน\nมีส่วนเชาวน์เลขและส่วนเชาวน์ไทย\nTPAT1 พาร์ตจริยธรรมแพทย์\n\nจำนวนข้อสอบแต่ละปียังไม่นิ่ง อ้างอิงจากข้อสอบ TPAT1 ของปี 67 ข้อสอบมี 55 ข้อ ซึ่งเท่ากับของปี 66 แต่ในปี 65 มี 60 ข้อ\nข้อสอบเป็นปรนัย 5 ตัวเลือก มีคำตอบที่ถูกเพียงข้อเดียว ทุกข้อคะแนนเท่ากัน คะแนนรวม 100 คะแนน เวลาสอบ 60 นาที\nข้อสอบมักแบ่งเป็น 2 แบบ คือ เหตุการณ์ทางการแพทย์และเหตุการณ์ทั่วไป โดยสัดส่วนจะแตกต่างกันไปในแต่ละปี\nTPAT1 พาร์ตความคิดเชื่อมโยง\n\nอ้างอิงจากข้อสอบ TPAT1 ของปี 67 ข้อสอบจะเป็นบทความเพียงบทความเดียว แต่ยาว 2 หน้ากระดาษ ใช้เวลาทำข้อสอบ 60 นาที\nโจทย์จะกำหนด 20 ข้อความที่ซ่อนอยู่ในบทความ น้อง ๆ จะต้องสรุปความเชื่อมโยงว่าแต่ละข้อความมีความเกี่ยวข้องกันยังไงบ้าง','ความถนัดแพทย์ กสพท','TPAT1','36'),(16,'d5k79biki2qos8ochqm8061a','คณิตศาสตร์เพิ่มเติ่ม','a-level',2500,0,'standard','0000-00-00 00:00:00','2025-03-02 06:39:46',NULL,1,1,NULL,24,'','Advance Math','A-LEVEL MATH1','96'),(28,'ybnb7ilc7o49ason8f616id7','พื้นฐานเคมี ม.ปลาย','a-level',2500,1,'standard','0000-00-00 00:00:00','2025-03-02 06:39:50',NULL,1,1,NULL,20,'บทเรียนเรื่อง อะตอมและตารางธาตุ\nบทเรียนย่อย\n     - โครงสร้างอะตอมและตารางธาตุ 1\n     - โครงสร้างอะตอมและตารางธาตุ 2\n     - โครงสร้างอะตอม 1\n     - โครงสร้างอะตอม 2\n     - โครงสร้างอะตอม 3\nแบบทดสอบความรู้\n     - แบบฝึกหัด วิชาเคมี ม. 4 เรื่อง โครงสร้างอะตอม\n     - แบบฝึกหัด วิชาเคมี ม. 4 เรื่อง อะตอมและตารางธาตุ ชุดที่ 1\n\n \n\nบทเรียนเรื่อง พันธะเคมี\nบทเรียนย่อย\n     - พันธะเคมี\n     - พันธะเคมี : พันธะไอออนิก และพันธะโลหะ\n\n \n\nบทเรียนเรื่อง สมบัติของธาตุและสารประกอบ\nบทเรียนย่อย\n     - เคมีนิวเคลียร์ (สมบัติของธาตุตามตาราง)\n\n \n\nบทเรียนเรื่อง ปริมาณสารสัมพันธ์\nบทเรียนย่อย\n     - ปริมาณสารสัมพันธ์ :โมลและสารละลาย\n     - ปริมาณสารสัมพันธ์ : สมการเคมี\n\n \n\nบทเรียนเรื่อง สมดุลเคมี\nบทเรียนย่อย\n     - สมดุลเคมี\n\n \n\nบทเรียนเรื่อง กรด - เบส\nบทเรียนย่อย\n     - กรด - เบส 1\n     - กรด - เบส 2\n\n \n\nบทเรียนเรื่อง ไฟฟ้าเคมี\nบทเรียนย่อย\n     - ไฟฟ้าเคมี\n\n \n\nบทเรียนเรื่อง เคมีอินทรีย์\nบทเรียนย่อย\n     - เคมีอินทรีย์ 1\n     - เคมีอินทรีย์ 2\n     - เคมีอินทรีย์\n\n \n\nบทเรียนเรื่อง เชื้อเพลิงซากดึกดำบรรพ์และผลิตภัณฑ์\nบทเรียนย่อย\n     - ปิโตรเลียมและพอลีเมอร์ (เชื้อเพลิงฯ)\n\n \n\nบทเรียนเรื่อง สารชีวโมเลกุล\nบทเรียนย่อย\n     - สารชีวโมเลกุล : โปรตีนและคาร์โบไฮเดรต\n     - สารชีวโมเลกุล : ไขมันและกรดนิวคลีอีก','chemistry','A-LEVEL CHEMISTRY','57'),(32,'kiihakuncg6db2wolxs7f6mn','คณิตศาสตร์พื้นฐาน 2','a-level',2000,1,'premium','0000-00-00 00:00:00','2025-03-02 06:39:53',NULL,1,1,NULL,16,'','Basic Math','A-LEVEL MATH2','32'),(113,'e8hqg9nf2dxoo1qrvoaefqwl','พื้นฐานชีวะ','a-level',999,NULL,'premium','0000-00-00 00:00:00','2025-03-02 06:40:00',NULL,1,1,NULL,98,NULL,'Basic Biology','A-LEVEL BIOLOGY','78'),(115,'rp0rdw4x5ygrn11cytyfpbcc','พิชิต TGAT1 60 ++','tgat',999,NULL,'premium','0000-00-00 00:00:00','2025-03-02 06:40:07',NULL,1,1,NULL,74,NULL,'Tgat Conversation, Speaking','TGAT1','78'),(119,'c2cru9e999232xfiipuwhfxp','พื้นฐานภาษาญี่ปุ่น','a-level',799,1,'premium','0000-00-00 00:00:00','2025-03-02 06:40:15',NULL,1,1,NULL,16,'ข้อสอบ A-Level 85 Jpn ภาษาญี่ปุ่น\nเป็นการวัดสมรรถนะการใช้ภาษาญี่ปุ่นในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการใช้ไวยากรณ์พื้นฐาน\n2) ความสามารถในการสื่อสาร\n3) ความสามารถในการเขียน\n4) ความสามารถในการอ่าน\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic Japanese','A-LEVEL JAPAN','16'),(121,'njlmtjmpcu2z6oidee6kglr1','พื้นฐานภาษาฝรั่งเศษ','a-level',499,1,'premium','0000-00-00 00:00:00','2025-03-02 06:40:20',NULL,NULL,1,NULL,14,'เป็นการวัดสมรรถนะการใช้ภาษาฝรั่งเศสในการสื่อสาร ประกอบด้วย\n1) ทักษะการสื่อสารทั่วไป\n1.1) การใช้คำศัพท์และสำนวน (5 ข้อ)\n1.2) การสื่อสารในสถานการณ์ชีวิตประจำวัน (10 ข้อ)\n15 ข้อ\n2) การใช้ไวยากรณ์พื้นฐาน\n15 ข้อ\n3) ความสามารถในการอ่านในชีวิตประจำวัน\n10 ข้อ\n4) ความสามารถในการเขียนในชีวิตประจำวัน\n8 ข้อ\n5) ความรู้ด้านวัฒนธรรมฝรั่งเศส\n2 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic France','A-LEVEL FRANCE','65'),(133,'s7v6hl0rieqciiszp9hi66hc','พื้นฐานวิทยาศาสตร์','a-level',399,1,'premium','0174-08-30 22:20:47','2025-03-02 06:40:30',NULL,NULL,1,NULL,24,NULL,'Basic Science','A-LEVEL SCIENCE','36'),(144,'woawnajjs4kqe6oplgmhfpt4','พื้นฐานภาษาสเปน','a-level',799,1,'standard','0000-00-00 00:00:00','2025-03-02 06:40:35',NULL,1,1,NULL,13,'ข้อสอบ A-Level 89 Esp ภาษาสเปน\nเป็นการวัดสมรรถนะการใช้ภาษาสเปนในการสื่อสาร ประกอบด้วย\n1) การใช้คำศัพท์และสำนวน และการสื่อสารในสถานการณ์ชีวิตประจำวัน\n2) ความสามารถในการเขียน และใช้ไวยากรณ์\n3) ความสามารถในการอ่าน และสังคมวัฒนธรรม\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic Spanish','A-LEVEL SPAIN','5'),(146,'exk6n32fsgyjtaimsyhn0vic','พิชิต Tpat 5 60 +','tpat',999,NULL,'standard','0000-00-00 00:00:00','2025-03-02 06:40:39',NULL,1,1,NULL,54,'ข้อสอบ TPAT5 50 ความถนัดครุศาสตร์-ศึกษาศาสตร์ ประกอบด้วย 2 ส่วนคือ\nส่วนที่ 1 : ความสามารถพื้นฐานทางวิชาชีพครู (50 คะแนน)\n1) ความสามารถทางการสื่อสาร 10 ข้อ\n2) ความสามารถทางการคิดวิเคราะห์ 10 ข้อ\n3) ความสามารถทางเทคโนโลยีสารสนเทศ 10 ข้อ\n4) ความสามารถทางการเข้าใจตนเองและผู้อื่น 10 ข้อ\n5) ความสามารถทางการคิดเพื่อการเรียนรู้ 10 ข้อ\n50 ข้อ\nส่วนที่ 2 : คุณลักษณะความเป็นครู (50 คะแนน)\n1) การมีมนุษยสัมพันธ์ 10 ข้อ\n2) ความรับผิดชอบต่อตนเองและสังคม ซื่อสัตย์ ยุติธรรม 10 ข้อ\n3) การเข้าใจและยอมรับผู้อื่น 10 ข้อ\n4) การเป็นผู้เรียนรู้และรักที่จะแบ่งปันความรู้ให้ผู้อื่น 10 ข้อ\n5) การส่งเสริมให้ผู้อื่นมีความคิดสร้างสรรค์และการเป็นผู้นำ 10 ข้อ\n50 ข้อ\nประเภทข้อสอบ ปรนัย (5 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 180 นาที','ความถนัดครุศาสตร์-ศึกษาศาสตร์','TPAT5','32'),(148,'piq3bya6z7yfecriawmarkcc','พิชิต Tpat 3 60 +','tpat',799,1,'standard','0000-00-00 00:00:00','2025-03-02 06:40:46',NULL,1,1,NULL,52,'ข้อสอบ TPAT3 30 ความถนัดด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ ประกอบด้วย 2 ส่วนคือ\nส่วนที่ 1: การทดสอบความถนัด (aptitude test) ด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ (60 คะแนน)\n1) ด้านตัวเลข (numerical reasoning) 15 ข้อ\n2) ด้านมิติสัมพันธ์ (diagrammatic reasoning) 15 ข้อ\n3) ด้านเชิงกล (mechanical reasoning) และด้านฟิสิกส์ (physics aptitude test) 15 ข้อ\n45 ข้อ\nส่วนที่ 2: การทดสอบความคิดและความสนใจทางด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ (40 คะแนน)\n1) ความคิดเชิงวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ 15 ข้อ\n2) ความสนใจข่าวสารความรู้ทางด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ 10 ข้อ\n25 ข้อ\nประเภทข้อสอบ ปรนัย (5 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 180 นาที','ความถนัดด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์','TPAT3','42'),(153,'ggc5odivys732pb20yyxqpct','พื้นฐานภาษาจีน','a-level',699,1,'premium','0000-00-00 00:00:00','2025-03-02 06:40:50',NULL,1,1,NULL,54,'เป็นการวัดสมรรถนะการใช้ภาษาจีนในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการใช้คำศัพท์และสำนวนภาษาจีนในชีวิตประจำวัน\n2) ความสามารถในการอ่านและสังคมวัฒนธรรม\n3) ความสามารถในการใช้ไวยากรณ์\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic Chinese','A-LEVEL CHINESE','34'),(155,'ykxz6jzq4h5sqzjexa7cgxg2','พื้นฐานภาษาเกาหลี ','a-level',799,1,'standard','0000-00-00 00:00:00','2025-03-02 06:40:54',NULL,1,1,NULL,36,'ข้อสอบ A-Level 86 Kor ภาษาเกาหลี\nเป็นการวัดสมรรถนะการใช้ภาษาเกาหลีในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการใช้คำศัพท์และสำนวนในชีวิตประจำวัน\n2) ความสามารถในการอ่านและสังคมวัฒนธรรม\n3) ความสามารถในการใช้ไวยากรณ์\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','안녕하세요','A-LEVEL KOREA','35'),(160,'hd6jb0u6uqm4mly4318dgizy','พื้นฐานภาษาเยอรมัน','a-level',599,NULL,'premium','0000-00-00 00:00:00','2025-03-02 06:40:59',NULL,1,1,NULL,36,'เป็นการวัดสมรรถนะการใช้ภาษาเยอรมันในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการเขียน\n20 ข้อ\n2) การใช้คำศัพท์และสำนวนภาษาเยอรมันในสถานการณ์ชีวิตประจำวัน\n10 ข้อ\n3) การอ่านตัวบทภาษาเยอรมัน\n20 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Wie geht es Ihnen?','A-LEVEL GERMANY','16'),(162,'enp0fqabv6mlb71r83x46yur','พื้นฐานภาษาไทย','a-level',699,1,'premium','0000-00-00 00:00:00','2025-03-02 06:41:03',NULL,1,1,NULL,36,'ส่วนที่ 1 : การอ่าน\n1) การอ่านเพื่อเข้าใจเนื้อหา\n2) การจับใจความ/การสรุปสาระสำคัญของข้อความ\n3) การตีความ\n4) การวิเคราะห์จุดประสงค์/เจตนาของผู้เขียน\n5) การวิเคราะห์ข้อคิด/แนวคิดที่ได้จากการอ่าน\n6) การอนุมานจากเนื้อหาของข้อความที่อ่าน\n7) ท่าที/น้ำเสียง/อารมณ์ความรู้สึก/ความคิดเห็นของผู้เขียน\nส่วนที่ 2 : การเขียน\n1) การเรียงลำดับข้อความ\n2) การเรียงความ\n3) การพรรณา/บรรยาย/อธิบาย\n4) การใช้เหตุผล\n5) การแสดงทรรศนะ\n6) การโต้แย้ง\n7) การโน้มน้าว\nส่วนที่ 3 : การพูด การฟัง\n1) การวิเคราะห์จุดประสงค์ในการพูด\n2) การใช้ข้อความถาม และตอบที่สัมพันธ์กัน\n3) การตีความ/อนุมาน/วิเคราะห์สาร/บุคลิกของผู้พูดหรือผู้ฟัง\nส่วนที่ 4 : หลักการใช้ภาษา\n1) การสะกดคำ\n2) การใช้คำตรงความหมาย\n3) ประโยคกำกวม/ประโยคบกพร่อง\n4) ประโยคสมบูรณ์\n5) ระดับภาษา\n6) การใช้สำนวนถูกต้องตามความหมาย\n7) ชนิดของประโยคตามเจตนา\n8) คำที่มีความหมายตรง/อุปมา\n9) คำทับศัพท์ภาษาอังกฤษ\n10) ราชาศัพท์\nประเภทข้อสอบ ปรนัย (5 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','สวัสดีครับ!','A-LEVEL THAI','35'),(176,'dx1cw4adn6njir1wjpfe6ho8','พื้นฐานภาษาบาลี','a-level',899,NULL,NULL,'0000-00-00 00:00:00','2025-03-02 06:41:07',NULL,1,1,NULL,24,'ส่วนที่ 1 : การอ่าน\nการอ่านเพื่อเข้าใจเนื้อหา\nการจับใจความ/สรุปสาระสำคัญ\nการตีความ\nการวิเคราะห์เจตนาผู้เขียน\nการวิเคราะห์ข้อคิด/แนวคิด\nการอนุมานจากข้อความ\nท่าที/อารมณ์ของผู้เขียน\nส่วนที่ 2 : การเขียน\nการเรียงลำดับข้อความ\nการเรียงความ\nการพรรณา/อธิบาย\nการใช้เหตุผล\nการแสดงทรรศนะ\nการโต้แย้ง\nการโน้มน้าว\nส่วนที่ 3 : การพูด/การฟัง\nการวิเคราะห์จุดประสงค์ในการพูด\nการถาม-ตอบสัมพันธ์กัน\nการตีความ/อนุมานสารจากผู้พูด/ฟัง\nส่วนที่ 4 : หลักการใช้ภาษา\nการสะกดคำ\nการใช้คำตรงความหมาย\nประโยคกำกวม/ประโยคสมบูรณ์\nระดับภาษา\nการใช้สำนวนถูกต้อง\nชนิดของประโยค\nคำทับศัพท์/ราชาศัพท์\n\n\n\n\n\n\n',NULL,'A-LEVEL BAHLI','12'),(178,'egntoc3b3m386kp3afzgxmnx','พิชิตสังคม alevel','a-level',999,1,NULL,'0000-00-00 00:00:00','2025-03-02 06:41:11',NULL,1,1,NULL,36,'รายละเอียดคอร์สสังคมศึกษา (36 ชั่วโมง)\nส่วนที่ 1: ความรู้เบื้องต้นเกี่ยวกับสังคม (9 ชั่วโมง)\nการศึกษาและการพัฒนาสังคม: การทำความเข้าใจเกี่ยวกับโครงสร้างสังคม การเปลี่ยนแปลงในสังคม\nความหลากหลายทางวัฒนธรรม: วัฒนธรรมและประเพณีที่หลากหลาย รวมถึงการเคารพความแตกต่าง\nบทบาทของพลเมืองในสังคม: สิทธิและหน้าที่พลเมือง รวมถึงการมีส่วนร่วมในกิจกรรมทางสังคม\nส่วนที่ 2: การเมืองและการปกครอง (9 ชั่วโมง)\nระบบการปกครอง: การศึกษาเกี่ยวกับระบบการปกครองทั้งในประเทศและระหว่างประเทศ\nการเมืองและประชาธิปไตย: การเข้าใจการทำงานของระบอบประชาธิปไตย รวมถึงการเลือกตั้ง\nสิทธิและเสรีภาพของประชาชน: สิทธิขั้นพื้นฐานและการปกป้องเสรีภาพในสังคม\nส่วนที่ 3: เศรษฐกิจและการเงิน (9 ชั่วโมง)\nเศรษฐกิจพื้นฐาน: หลักการพื้นฐานของเศรษฐกิจ การผลิต การบริโภค และการกระจายรายได้\nระบบการเงินและการธนาคาร: การทำความเข้าใจเกี่ยวกับการดำเนินการทางการเงินและบทบาทของธนาคาร\nการพัฒนาเศรษฐกิจและความยั่งยืน: วิธีการพัฒนาเศรษฐกิจอย่างยั่งยืนและการจัดการทรัพยากร\nส่วนที่ 4: สังคมและเทคโนโลยี (9 ชั่วโมง)\nการเปลี่ยนแปลงทางสังคมจากเทคโนโลยี: ผลกระทบจากการพัฒนาเทคโนโลยีในด้านต่างๆ\nสังคมออนไลน์และการสื่อสาร: การใช้สื่อสังคมและผลกระทบที่เกิดขึ้น\nเทคโนโลยีกับการพัฒนาในอนาคต: การคาดการณ์อนาคตในแง่ของเทคโนโลยีและสังคม\nวิธีการเรียนการสอน:\nการบรรยาย, การทำแบบฝึกหัด และการอภิปรายในกลุ่ม\nการศึกษากรณีตัวอย่างที่เกี่ยวข้องกับสังคม การเมือง เศรษฐกิจ และเทคโนโลยี\nการใช้สื่อการสอนออนไลน์และการทำกิจกรรมร่วมกัน\nวัตถุประสงค์:\nเพื่อให้ผู้เรียนมีความเข้าใจในสังคม การเมือง เศรษฐกิจ และวัฒนธรรม\nเพื่อพัฒนาความสามารถในการวิเคราะห์และประเมินสถานการณ์ทางสังคม\nเพื่อส่งเสริมการมีส่วนร่วมในสังคมและการตัดสินใจที่มีความรับผิดชอบ\n',NULL,'A-LEVEL SOCIAL','12'),(189,'ekm9wxgaqsaur4fnsoyhmlmv','พิชิต TGAT2 60 ++','tgat',150,1,'standard','0000-00-00 00:00:00','2025-03-02 06:41:17',NULL,1,1,NULL,34,NULL,'Tgat2','TGAT2','4'),(194,'y7xymkj6jpsuvstemsi36c16','พิชิต TPAT2 60 ++','tpat',500,NULL,'standard','0000-00-00 00:00:00','2025-03-02 06:41:20',NULL,1,1,NULL,65,NULL,'Tpat2','TPAT2','45'),(196,'vv8cy75pgz6651x0e6ogzilt','พิชิต TPAT4 60 ++','tpat',634,NULL,'standard','0000-00-00 00:00:00','2025-03-02 06:41:25',NULL,1,1,NULL,54,NULL,'Tpat4','TPAT4','10'),(200,'b5r942mjfak761itbo970xoq','พื้นฐานภาษาอังกฤษ','tgat',2000,1,'standard',NULL,'2025-03-02 06:39:27','2025-03-02 06:39:27',1,1,NULL,20,'TGAT คืออะไร ? TGAT หรือ Thailand General Aptitude Test คือวิชาที่วัดความถนัดทั่วไป มีด้วยกันทั้งหมด 3 พาร์ท คือ English Communication (การสื่อสารภาษาอังกฤษ) Critical and Logical Thinking (การคิดอย่างมีเหตุผล) GAT คืออะไร ? TGAT หรือ Thailand General Aptitude Test คือวิชาที่วัดความถนัดทั่วไป มีด้วยกันทั้งหมด 3 พาร์ท คือ English Communication (การสื่อสารภาษาอังกฤษ) Critical and Logical Thinking (การคิดอย่างมีเหตุผล)GAT คืออะไร ? TGAT หรือ Thailand General Aptitude Test คือวิชาที่วัดความถนัดทั่วไป มีด้วยกันทั้งหมด 3 พาร์ท คือ English Communication (การสื่อสารภาษาอังกฤษ) Critical and Logical Thinking (การคิดอย่างมีเหตุผล)','Basic English','A-LEVEL ENGLISH','8'),(201,'mwh71za9i86rn020hprvklzs','พื้นฐานฟิสิกส์','a-level',2000,1,'premium',NULL,'2025-03-02 06:39:35','2025-03-02 06:39:35',1,1,NULL,24,'ข้อสอบวิชาฟิสิกส์ A-Level คือข้อสอบที่มาแทนวิชาฟิสิกส์สามัญ เนื้อหาที่ออกข้อสอบจะมาจากเนื้อหาที่ได้เรียน โดยเน้นการนำไปประยุกต์ใช้ แบ่งเป็น 5 พาร์ทด้วยกัน ได้แก่ กลศาสตร์, คลื่นกลและแสง, ไฟฟ้าแม่เหล็กและคลื่นแม่เหล็กไฟฟ้า, อุณหพลศาสตร์และสมบัติเชิงกลของสารและฟิสิกส์แผนใหม่ ข้อสอบแบ่งเป็นปรนัย 5 ตัวเลือก 25 ข้อและอัตนัยในรูปแบบเลือกระบายค่าตัวเลขจำนวน 5 ข้อ รวมคะแนนทั้งสิ้นเต็ม 100 คะแนน ซึ่งข้อสอบจะมีความแตกต่างจากวิชาคณิตศาสตร์ประยุกต์1 และ 2 ที่ตัวข้อสอบอัตนัยจะไม่ได้เป็นข้อเขียนเต็มนั่นเอง\n\nระยะเวลาสอบ: 90 นาที\nจำนวนคะแนน: 30 ข้อคะแนนเต็ม 100 คะแนน (ปรนัย 26 ข้อ = 75 คะแนน / อัตนัย 4 ข้อ = 25 คะแนน)\nค่าสอบ: 100.-\nใครควรสอบ: น้องๆ สายวิทย์-คณิต \nข้อสอบออกอะไรบ้าง ? :\nกลศาสตร์ ธรรมชาติและพัฒนาการทางฟิสิกส์, การเคลื่อนที่แนวตรง, แรงและกฎการเคลื่อนที่, สมดุลกลของวัตถุ, งานและกฎการอนุรักษ์พลังงานกล, โมเมนตัมและการชน, การเคลื่อนที่แนวโค้งและการเคลื่อนที่แบบฮาร์มอนิกส์อย่างง่าย\nคลื่นกลและแสง แสง คลื่นและเสียง\nไฟฟ้าแม่เหล็กและคลื่นแม่เหล็กไฟฟ้า ไฟฟ้าสถิต, ไฟฟ้ากระแส, แม่เหล็กและไฟฟ้าและคลื่นแม่เหล็กไฟฟ้า\nอุณหพลศาสตร์และสมบัติเชิงกลของสาร ความร้อนและแก๊ส ของแข็งและของไหล\nฟิสิกส์แผนใหม่ ฟิสิกส์อะตอมและฟิสิกส์นิวเคลียร์และฟิสิกส์อนุภาค','Basic Physics','A-LEVEL PHYSICS','10'),(202,'q4wvtdq484brc82jpr3019d5','พิชิต Tpat 1 60 +','tpat',899,1,'premium',NULL,'2025-03-02 06:39:39','2025-03-02 06:39:39',1,1,NULL,24,'TPAT1 พาร์ตเชาวน์ปัญญา\n\nมี 45 ข้อ เวลาสอบ 75 นาที เฉล่ียเวลาข้อละ 1 นาที 40 วินาที\nข้อสอบเป็นปรนัย 5 ตัวเลือก ทุกข้อคะแนนเท่ากัน คะแนนรวม 100 คะแนน\nมีส่วนเชาวน์เลขและส่วนเชาวน์ไทย\nTPAT1 พาร์ตจริยธรรมแพทย์\n\nจำนวนข้อสอบแต่ละปียังไม่นิ่ง อ้างอิงจากข้อสอบ TPAT1 ของปี 67 ข้อสอบมี 55 ข้อ ซึ่งเท่ากับของปี 66 แต่ในปี 65 มี 60 ข้อ\nข้อสอบเป็นปรนัย 5 ตัวเลือก มีคำตอบที่ถูกเพียงข้อเดียว ทุกข้อคะแนนเท่ากัน คะแนนรวม 100 คะแนน เวลาสอบ 60 นาที\nข้อสอบมักแบ่งเป็น 2 แบบ คือ เหตุการณ์ทางการแพทย์และเหตุการณ์ทั่วไป โดยสัดส่วนจะแตกต่างกันไปในแต่ละปี\nTPAT1 พาร์ตความคิดเชื่อมโยง\n\nอ้างอิงจากข้อสอบ TPAT1 ของปี 67 ข้อสอบจะเป็นบทความเพียงบทความเดียว แต่ยาว 2 หน้ากระดาษ ใช้เวลาทำข้อสอบ 60 นาที\nโจทย์จะกำหนด 20 ข้อความที่ซ่อนอยู่ในบทความ น้อง ๆ จะต้องสรุปความเชื่อมโยงว่าแต่ละข้อความมีความเกี่ยวข้องกันยังไงบ้าง','ความถนัดแพทย์ กสพท','TPAT1','36'),(203,'d5k79biki2qos8ochqm8061a','คณิตศาสตร์เพิ่มเติ่ม','a-level',2500,0,'standard',NULL,'2025-03-02 06:39:46','2025-03-02 06:39:46',1,1,NULL,24,'','Advance Math','A-LEVEL MATH1','96'),(204,'ybnb7ilc7o49ason8f616id7','พื้นฐานเคมี ม.ปลาย','a-level',2500,1,'standard',NULL,'2025-03-02 06:39:50','2025-03-02 06:39:50',1,1,NULL,20,'บทเรียนเรื่อง อะตอมและตารางธาตุ\nบทเรียนย่อย\n     - โครงสร้างอะตอมและตารางธาตุ 1\n     - โครงสร้างอะตอมและตารางธาตุ 2\n     - โครงสร้างอะตอม 1\n     - โครงสร้างอะตอม 2\n     - โครงสร้างอะตอม 3\nแบบทดสอบความรู้\n     - แบบฝึกหัด วิชาเคมี ม. 4 เรื่อง โครงสร้างอะตอม\n     - แบบฝึกหัด วิชาเคมี ม. 4 เรื่อง อะตอมและตารางธาตุ ชุดที่ 1\n\n \n\nบทเรียนเรื่อง พันธะเคมี\nบทเรียนย่อย\n     - พันธะเคมี\n     - พันธะเคมี : พันธะไอออนิก และพันธะโลหะ\n\n \n\nบทเรียนเรื่อง สมบัติของธาตุและสารประกอบ\nบทเรียนย่อย\n     - เคมีนิวเคลียร์ (สมบัติของธาตุตามตาราง)\n\n \n\nบทเรียนเรื่อง ปริมาณสารสัมพันธ์\nบทเรียนย่อย\n     - ปริมาณสารสัมพันธ์ :โมลและสารละลาย\n     - ปริมาณสารสัมพันธ์ : สมการเคมี\n\n \n\nบทเรียนเรื่อง สมดุลเคมี\nบทเรียนย่อย\n     - สมดุลเคมี\n\n \n\nบทเรียนเรื่อง กรด - เบส\nบทเรียนย่อย\n     - กรด - เบส 1\n     - กรด - เบส 2\n\n \n\nบทเรียนเรื่อง ไฟฟ้าเคมี\nบทเรียนย่อย\n     - ไฟฟ้าเคมี\n\n \n\nบทเรียนเรื่อง เคมีอินทรีย์\nบทเรียนย่อย\n     - เคมีอินทรีย์ 1\n     - เคมีอินทรีย์ 2\n     - เคมีอินทรีย์\n\n \n\nบทเรียนเรื่อง เชื้อเพลิงซากดึกดำบรรพ์และผลิตภัณฑ์\nบทเรียนย่อย\n     - ปิโตรเลียมและพอลีเมอร์ (เชื้อเพลิงฯ)\n\n \n\nบทเรียนเรื่อง สารชีวโมเลกุล\nบทเรียนย่อย\n     - สารชีวโมเลกุล : โปรตีนและคาร์โบไฮเดรต\n     - สารชีวโมเลกุล : ไขมันและกรดนิวคลีอีก','chemistry','A-LEVEL CHEMISTRY','57'),(205,'kiihakuncg6db2wolxs7f6mn','คณิตศาสตร์พื้นฐาน 2','a-level',2000,1,'premium',NULL,'2025-03-02 06:39:53','2025-03-02 06:39:53',1,1,NULL,16,'','Basic Math','A-LEVEL MATH2','32'),(206,'e8hqg9nf2dxoo1qrvoaefqwl','พื้นฐานชีวะ','a-level',999,NULL,'premium',NULL,'2025-03-02 06:40:00','2025-03-02 06:40:00',1,1,NULL,98,NULL,'Basic Biology','A-LEVEL BIOLOGY','78'),(207,'rp0rdw4x5ygrn11cytyfpbcc','พิชิต TGAT1 60 ++','tgat',999,NULL,'premium',NULL,'2025-03-02 06:40:07','2025-03-02 06:40:07',1,1,NULL,74,NULL,'Tgat Conversation, Speaking','TGAT1','78'),(208,'c2cru9e999232xfiipuwhfxp','พื้นฐานภาษาญี่ปุ่น','a-level',799,1,'premium',NULL,'2025-03-02 06:40:15','2025-03-02 06:40:15',1,1,NULL,16,'ข้อสอบ A-Level 85 Jpn ภาษาญี่ปุ่น\nเป็นการวัดสมรรถนะการใช้ภาษาญี่ปุ่นในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการใช้ไวยากรณ์พื้นฐาน\n2) ความสามารถในการสื่อสาร\n3) ความสามารถในการเขียน\n4) ความสามารถในการอ่าน\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic Japanese','A-LEVEL JAPAN','16'),(209,'njlmtjmpcu2z6oidee6kglr1','พื้นฐานภาษาฝรั่งเศษ','a-level',499,1,'premium',NULL,'2025-03-02 06:40:20','2025-03-02 06:40:20',NULL,1,NULL,14,'เป็นการวัดสมรรถนะการใช้ภาษาฝรั่งเศสในการสื่อสาร ประกอบด้วย\n1) ทักษะการสื่อสารทั่วไป\n1.1) การใช้คำศัพท์และสำนวน (5 ข้อ)\n1.2) การสื่อสารในสถานการณ์ชีวิตประจำวัน (10 ข้อ)\n15 ข้อ\n2) การใช้ไวยากรณ์พื้นฐาน\n15 ข้อ\n3) ความสามารถในการอ่านในชีวิตประจำวัน\n10 ข้อ\n4) ความสามารถในการเขียนในชีวิตประจำวัน\n8 ข้อ\n5) ความรู้ด้านวัฒนธรรมฝรั่งเศส\n2 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic France','A-LEVEL FRANCE','65'),(210,'s7v6hl0rieqciiszp9hi66hc','พื้นฐานวิทยาศาสตร์','a-level',399,1,'premium','0174-08-30 22:20:47','2025-03-02 06:40:30','2025-03-02 06:40:30',NULL,1,NULL,24,NULL,'Basic Science','A-LEVEL SCIENCE','36'),(211,'woawnajjs4kqe6oplgmhfpt4','พื้นฐานภาษาสเปน','a-level',799,1,'standard',NULL,'2025-03-02 06:40:35','2025-03-02 06:40:35',1,1,NULL,13,'ข้อสอบ A-Level 89 Esp ภาษาสเปน\nเป็นการวัดสมรรถนะการใช้ภาษาสเปนในการสื่อสาร ประกอบด้วย\n1) การใช้คำศัพท์และสำนวน และการสื่อสารในสถานการณ์ชีวิตประจำวัน\n2) ความสามารถในการเขียน และใช้ไวยากรณ์\n3) ความสามารถในการอ่าน และสังคมวัฒนธรรม\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic Spanish','A-LEVEL SPAIN','5'),(212,'exk6n32fsgyjtaimsyhn0vic','พิชิต Tpat 5 60 +','tpat',999,NULL,'standard',NULL,'2025-03-02 06:40:39','2025-03-02 06:40:39',1,1,NULL,54,'ข้อสอบ TPAT5 50 ความถนัดครุศาสตร์-ศึกษาศาสตร์ ประกอบด้วย 2 ส่วนคือ\nส่วนที่ 1 : ความสามารถพื้นฐานทางวิชาชีพครู (50 คะแนน)\n1) ความสามารถทางการสื่อสาร 10 ข้อ\n2) ความสามารถทางการคิดวิเคราะห์ 10 ข้อ\n3) ความสามารถทางเทคโนโลยีสารสนเทศ 10 ข้อ\n4) ความสามารถทางการเข้าใจตนเองและผู้อื่น 10 ข้อ\n5) ความสามารถทางการคิดเพื่อการเรียนรู้ 10 ข้อ\n50 ข้อ\nส่วนที่ 2 : คุณลักษณะความเป็นครู (50 คะแนน)\n1) การมีมนุษยสัมพันธ์ 10 ข้อ\n2) ความรับผิดชอบต่อตนเองและสังคม ซื่อสัตย์ ยุติธรรม 10 ข้อ\n3) การเข้าใจและยอมรับผู้อื่น 10 ข้อ\n4) การเป็นผู้เรียนรู้และรักที่จะแบ่งปันความรู้ให้ผู้อื่น 10 ข้อ\n5) การส่งเสริมให้ผู้อื่นมีความคิดสร้างสรรค์และการเป็นผู้นำ 10 ข้อ\n50 ข้อ\nประเภทข้อสอบ ปรนัย (5 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 180 นาที','ความถนัดครุศาสตร์-ศึกษาศาสตร์','TPAT5','32'),(213,'piq3bya6z7yfecriawmarkcc','พิชิต Tpat 3 60 +','tpat',799,1,'standard',NULL,'2025-03-02 06:40:46','2025-03-02 06:40:46',1,1,NULL,52,'ข้อสอบ TPAT3 30 ความถนัดด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ ประกอบด้วย 2 ส่วนคือ\nส่วนที่ 1: การทดสอบความถนัด (aptitude test) ด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ (60 คะแนน)\n1) ด้านตัวเลข (numerical reasoning) 15 ข้อ\n2) ด้านมิติสัมพันธ์ (diagrammatic reasoning) 15 ข้อ\n3) ด้านเชิงกล (mechanical reasoning) และด้านฟิสิกส์ (physics aptitude test) 15 ข้อ\n45 ข้อ\nส่วนที่ 2: การทดสอบความคิดและความสนใจทางด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ (40 คะแนน)\n1) ความคิดเชิงวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ 15 ข้อ\n2) ความสนใจข่าวสารความรู้ทางด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์ 10 ข้อ\n25 ข้อ\nประเภทข้อสอบ ปรนัย (5 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 180 นาที','ความถนัดด้านวิทยาศาสตร์ เทคโนโลยี และวิศวกรรมศาสตร์','TPAT3','42'),(214,'ggc5odivys732pb20yyxqpct','พื้นฐานภาษาจีน','a-level',699,1,'premium',NULL,'2025-03-02 06:40:50','2025-03-02 06:40:50',1,1,NULL,54,'เป็นการวัดสมรรถนะการใช้ภาษาจีนในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการใช้คำศัพท์และสำนวนภาษาจีนในชีวิตประจำวัน\n2) ความสามารถในการอ่านและสังคมวัฒนธรรม\n3) ความสามารถในการใช้ไวยากรณ์\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Basic Chinese','A-LEVEL CHINESE','34'),(215,'ykxz6jzq4h5sqzjexa7cgxg2','พื้นฐานภาษาเกาหลี ','a-level',799,1,'standard',NULL,'2025-03-02 06:40:54','2025-03-02 06:40:54',1,1,NULL,36,'ข้อสอบ A-Level 86 Kor ภาษาเกาหลี\nเป็นการวัดสมรรถนะการใช้ภาษาเกาหลีในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการใช้คำศัพท์และสำนวนในชีวิตประจำวัน\n2) ความสามารถในการอ่านและสังคมวัฒนธรรม\n3) ความสามารถในการใช้ไวยากรณ์\n50 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','안녕하세요','A-LEVEL KOREA','35'),(216,'hd6jb0u6uqm4mly4318dgizy','พื้นฐานภาษาเยอรมัน','a-level',599,NULL,'premium',NULL,'2025-03-02 06:40:59','2025-03-02 06:40:59',1,1,NULL,36,'เป็นการวัดสมรรถนะการใช้ภาษาเยอรมันในการสื่อสาร ประกอบด้วย\n1) ความสามารถในการเขียน\n20 ข้อ\n2) การใช้คำศัพท์และสำนวนภาษาเยอรมันในสถานการณ์ชีวิตประจำวัน\n10 ข้อ\n3) การอ่านตัวบทภาษาเยอรมัน\n20 ข้อ\nประเภทข้อสอบ ปรนัย (4 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','Wie geht es Ihnen?','A-LEVEL GERMANY','16'),(217,'enp0fqabv6mlb71r83x46yur','พื้นฐานภาษาไทย','a-level',699,1,'premium',NULL,'2025-03-02 06:41:03','2025-03-02 06:41:03',1,1,NULL,36,'ส่วนที่ 1 : การอ่าน\n1) การอ่านเพื่อเข้าใจเนื้อหา\n2) การจับใจความ/การสรุปสาระสำคัญของข้อความ\n3) การตีความ\n4) การวิเคราะห์จุดประสงค์/เจตนาของผู้เขียน\n5) การวิเคราะห์ข้อคิด/แนวคิดที่ได้จากการอ่าน\n6) การอนุมานจากเนื้อหาของข้อความที่อ่าน\n7) ท่าที/น้ำเสียง/อารมณ์ความรู้สึก/ความคิดเห็นของผู้เขียน\nส่วนที่ 2 : การเขียน\n1) การเรียงลำดับข้อความ\n2) การเรียงความ\n3) การพรรณา/บรรยาย/อธิบาย\n4) การใช้เหตุผล\n5) การแสดงทรรศนะ\n6) การโต้แย้ง\n7) การโน้มน้าว\nส่วนที่ 3 : การพูด การฟัง\n1) การวิเคราะห์จุดประสงค์ในการพูด\n2) การใช้ข้อความถาม และตอบที่สัมพันธ์กัน\n3) การตีความ/อนุมาน/วิเคราะห์สาร/บุคลิกของผู้พูดหรือผู้ฟัง\nส่วนที่ 4 : หลักการใช้ภาษา\n1) การสะกดคำ\n2) การใช้คำตรงความหมาย\n3) ประโยคกำกวม/ประโยคบกพร่อง\n4) ประโยคสมบูรณ์\n5) ระดับภาษา\n6) การใช้สำนวนถูกต้องตามความหมาย\n7) ชนิดของประโยคตามเจตนา\n8) คำที่มีความหมายตรง/อุปมา\n9) คำทับศัพท์ภาษาอังกฤษ\n10) ราชาศัพท์\nประเภทข้อสอบ ปรนัย (5 ตัวเลือก)\nระยะเวลาที่ใช้สอบ 90 นาที','สวัสดีครับ!','A-LEVEL THAI','35'),(218,'dx1cw4adn6njir1wjpfe6ho8','พื้นฐานภาษาบาลี','a-level',899,NULL,NULL,NULL,'2025-03-02 06:41:07','2025-03-02 06:41:07',1,1,NULL,24,'ส่วนที่ 1 : การอ่าน\nการอ่านเพื่อเข้าใจเนื้อหา\nการจับใจความ/สรุปสาระสำคัญ\nการตีความ\nการวิเคราะห์เจตนาผู้เขียน\nการวิเคราะห์ข้อคิด/แนวคิด\nการอนุมานจากข้อความ\nท่าที/อารมณ์ของผู้เขียน\nส่วนที่ 2 : การเขียน\nการเรียงลำดับข้อความ\nการเรียงความ\nการพรรณา/อธิบาย\nการใช้เหตุผล\nการแสดงทรรศนะ\nการโต้แย้ง\nการโน้มน้าว\nส่วนที่ 3 : การพูด/การฟัง\nการวิเคราะห์จุดประสงค์ในการพูด\nการถาม-ตอบสัมพันธ์กัน\nการตีความ/อนุมานสารจากผู้พูด/ฟัง\nส่วนที่ 4 : หลักการใช้ภาษา\nการสะกดคำ\nการใช้คำตรงความหมาย\nประโยคกำกวม/ประโยคสมบูรณ์\nระดับภาษา\nการใช้สำนวนถูกต้อง\nชนิดของประโยค\nคำทับศัพท์/ราชาศัพท์\n\n\n\n\n\n\n',NULL,'A-LEVEL BAHLI','12'),(219,'egntoc3b3m386kp3afzgxmnx','พิชิตสังคม alevel','a-level',999,1,NULL,NULL,'2025-03-02 06:41:11','2025-03-02 06:41:11',1,1,NULL,36,'รายละเอียดคอร์สสังคมศึกษา (36 ชั่วโมง)\nส่วนที่ 1: ความรู้เบื้องต้นเกี่ยวกับสังคม (9 ชั่วโมง)\nการศึกษาและการพัฒนาสังคม: การทำความเข้าใจเกี่ยวกับโครงสร้างสังคม การเปลี่ยนแปลงในสังคม\nความหลากหลายทางวัฒนธรรม: วัฒนธรรมและประเพณีที่หลากหลาย รวมถึงการเคารพความแตกต่าง\nบทบาทของพลเมืองในสังคม: สิทธิและหน้าที่พลเมือง รวมถึงการมีส่วนร่วมในกิจกรรมทางสังคม\nส่วนที่ 2: การเมืองและการปกครอง (9 ชั่วโมง)\nระบบการปกครอง: การศึกษาเกี่ยวกับระบบการปกครองทั้งในประเทศและระหว่างประเทศ\nการเมืองและประชาธิปไตย: การเข้าใจการทำงานของระบอบประชาธิปไตย รวมถึงการเลือกตั้ง\nสิทธิและเสรีภาพของประชาชน: สิทธิขั้นพื้นฐานและการปกป้องเสรีภาพในสังคม\nส่วนที่ 3: เศรษฐกิจและการเงิน (9 ชั่วโมง)\nเศรษฐกิจพื้นฐาน: หลักการพื้นฐานของเศรษฐกิจ การผลิต การบริโภค และการกระจายรายได้\nระบบการเงินและการธนาคาร: การทำความเข้าใจเกี่ยวกับการดำเนินการทางการเงินและบทบาทของธนาคาร\nการพัฒนาเศรษฐกิจและความยั่งยืน: วิธีการพัฒนาเศรษฐกิจอย่างยั่งยืนและการจัดการทรัพยากร\nส่วนที่ 4: สังคมและเทคโนโลยี (9 ชั่วโมง)\nการเปลี่ยนแปลงทางสังคมจากเทคโนโลยี: ผลกระทบจากการพัฒนาเทคโนโลยีในด้านต่างๆ\nสังคมออนไลน์และการสื่อสาร: การใช้สื่อสังคมและผลกระทบที่เกิดขึ้น\nเทคโนโลยีกับการพัฒนาในอนาคต: การคาดการณ์อนาคตในแง่ของเทคโนโลยีและสังคม\nวิธีการเรียนการสอน:\nการบรรยาย, การทำแบบฝึกหัด และการอภิปรายในกลุ่ม\nการศึกษากรณีตัวอย่างที่เกี่ยวข้องกับสังคม การเมือง เศรษฐกิจ และเทคโนโลยี\nการใช้สื่อการสอนออนไลน์และการทำกิจกรรมร่วมกัน\nวัตถุประสงค์:\nเพื่อให้ผู้เรียนมีความเข้าใจในสังคม การเมือง เศรษฐกิจ และวัฒนธรรม\nเพื่อพัฒนาความสามารถในการวิเคราะห์และประเมินสถานการณ์ทางสังคม\nเพื่อส่งเสริมการมีส่วนร่วมในสังคมและการตัดสินใจที่มีความรับผิดชอบ\n',NULL,'A-LEVEL SOCIAL','12'),(220,'ekm9wxgaqsaur4fnsoyhmlmv','พิชิต TGAT2 60 ++','tgat',150,1,'standard',NULL,'2025-03-02 06:41:17','2025-03-02 06:41:17',1,1,NULL,34,NULL,'Tgat2','TGAT2','4'),(221,'y7xymkj6jpsuvstemsi36c16','พิชิต TPAT2 60 ++','tpat',500,NULL,'standard',NULL,'2025-03-02 06:41:20','2025-03-02 06:41:20',1,1,NULL,65,NULL,'Tpat2','TPAT2','45'),(222,'vv8cy75pgz6651x0e6ogzilt','พิชิต TPAT4 60 ++','tpat',634,NULL,'standard',NULL,'2025-03-02 06:41:25','2025-03-02 06:41:25',1,1,NULL,54,NULL,'Tpat4','TPAT4','10');
